struct mount_attr {
    unsigned long long attr_set;
    unsigned long long attr_clr;
    unsigned long long propagation;
};

// Define necessary constants (Placeholders)
#define AT_FDCWD           (-100)
#define MOUNT_ATTR_RDONLY  (1ULL << 0)
#define MOUNT_ATTR_PRIVATE (1ULL << 10)

struct mount_attr ma = {0};

// Set the mount to Read-Only and change propagation to Private
ma.attr_set = MOUNT_ATTR_RDONLY;
ma.propagation = MOUNT_ATTR_PRIVATE;

// Apply attributes to the mount point "/mnt/data"
int result = mount_setattr(
    AT_FDCWD,
    "/mnt/data",
    0, // Path resolution flags
    &ma
);
